    flowOf(1, 2, 3)
        .filter { it % 2 != 0 }
        .collect { print(it) }
}

runBlocking {
    flow {
        emit("A")
        delay(10)
        emit("B")
    }.conflate().collect {
        print("$it ")
    }
}

val mutex = Mutex()
var count = 0
runBlocking {
    withContext(Dispatchers.Default) {
        val jobs = List(1000) {
            launch {
                mutex.withLock { count++ }
            }
        }
        jobs.forEach { it.join() }
    }
}
println(count)

