runBlocking {
    val d1 = async { 10 }
    val d2 = async { 20 }
    println(d1.await() + d2.await())
}

runBlocking {
    val channel = Channel<Int>()
    launch { channel.send(99) }
    println(channel.receive())
}

runBlocking {
    val c1 = Channel<String>()
    val c2 = Channel<String>()
    launch { c1.send("First") }
    val res = select<String> {
        c1.onReceive { it }
        c2.onReceive { it }
    }
    println(res)
}

runBlocking {
    val job = launch {
        try {
            delay(1000)
        } catch (e: CancellationException) {
            print("Canceled ")
        }
    }
    delay(100)
    job.cancelAndJoin()
    print("Done")
}

runBlocking {
    supervisorScope {
        val child1 = launch {
            throw RuntimeException("Failed")
        }
        val child2 = launch {
            delay(100)
            print("Survived ")
        }
    }
    print("Done")
}

val handler = CoroutineExceptionHandler { _, exception ->
    print("Handled ")
}
runBlocking {
    val job = GlobalScope.launch(handler) {
        throw AssertionError("Failed")
    }
    job.join()
    print("End")
}

data class Point(val x: Int) {
